import { describe, it, expect } from "vitest";
import {
  createBranchHistoryImport,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
  BRANCH_HISTORY_SCHEMA,
  branchMessageDigest,
} from "../src/lib/session-branch-history.js";

const HEX = (ch) => ch.repeat(64);

/**
 * Feed events into a fresh branch-history importer and collect every return
 * value, or let the importer's validation error propagate.
 */
function feed(events) {
  const importer = createBranchHistoryImport();
  const results = [];
  for (const event of events) {
    results.push(importer.accept(event));
  }
  return results;
}

function descriptor({ totalMessages, contextMessageCount }) {
  return {
    schema: BRANCH_HISTORY_SCHEMA,
    sourceGeneration: HEX("a"),
    totalMessages,
    contextMessageCount,
    coverage: { kind: "from-origin", boundaryEvent: null, reason: null },
  };
}

function start(sessionId) {
  return { type: "session_start", data: { sessionId } };
}

function branchEvent(desc) {
  return { type: "session_branch", data: { history: desc } };
}

function row(role, text, i) {
  return {
    type: BRANCH_HISTORY_MESSAGE,
    data: {
      role,
      text,
      part: 0,
      last: true,
      sourceEventId: HEX(String(i + 1)),
      sourceItemIndex: i,
    },
  };
}

const archive = (results) =>
  results
    .filter((r) => r && r.kind === "archive")
    .map((r) => r.message);

describe("fork history attribution (verify-08)", () => {
  it("recovers each branch's independent body without cross-leak", () => {
    const branchA = feed([
      start("a"),
      branchEvent(descriptor({ totalMessages: 2, contextMessageCount: 0 })),
      row("user", "A1", 0),
      row("assistant", "A2", 1),
    ]);
    expect(branchA[0]).toEqual({
      kind: "start",
      coverage: { kind: "from-origin", boundaryEvent: null, reason: null },
    });
    expect(archive(branchA)).toEqual([
      { role: "user", content: "A1" },
      { role: "assistant", content: "A2" },
    ]);

    const branchB = feed([
      start("b"),
      branchEvent(descriptor({ totalMessages: 1, contextMessageCount: 0 })),
      row("assistant", "B1", 0),
    ]);
    expect(archive(branchB)).toEqual([{ role: "assistant", content: "B1" }]);

    // Post-branch content must never leak into a sibling branch's body.
    expect(archive(branchB)[0].content).toBe("B1");
    expect(archive(branchB)[0].content).not.toContain("A1");
    expect(archive(branchA).map((m) => m.content).join()).not.toContain("B1");
  });

  it("rejects ancestry content when the branch declares no context slots", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 0 });
    expect(() =>
      feed([start("x"), branchEvent(desc), row("user", "pre", 0), {
        type: "user_message",
        data: { role: "user" },
      }]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("rejects a context event whose role does not match its event type", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 1 });
    expect(() =>
      feed([start("x"), branchEvent(desc), row("user", "pre", 0), {
        type: "user_message",
        data: { role: "assistant" },
      }]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("rejects body rows beyond the branch's declared totalMessages", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 0 });
    expect(() =>
      feed([
        start("x"),
        branchEvent(desc),
        row("user", "one", 0),
        row("assistant", "overflow", 1),
      ]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("rejects a completion with a non-v2 schema even when counts align", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 0 });
    expect(() =>
      feed([
        start("x"),
        branchEvent(desc),
        row("user", "one", 0),
        { type: "session_branch_complete", data: { schemaVersion: 1 } },
      ]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("resolves a context message's ancestry origin within the branch's own rows", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 1 });
    const userCtx = { role: "user" };

    // Positive: a non-null origin pointing at an archived row is accepted.
    const positive = feed([
      start("x"),
      branchEvent(desc),
      row("user", "pre", 0),
      { type: "user_message", data: userCtx },
      {
        type: BRANCH_HISTORY_ORIGIN,
        data: {
          messageDigest: branchMessageDigest(userCtx),
          origin: { first: 0, last: 0 },
        },
      },
    ]);
    expect(positive.map((r) => r && r.kind)).toContain("context");

    // Negative: a null origin is only valid for a system role, so the same
    // user-context stream is rejected when origin is null.
    expect(() =>
      feed([
        start("x"),
        branchEvent(desc),
        row("user", "pre", 0),
        { type: "user_message", data: userCtx },
        {
          type: BRANCH_HISTORY_ORIGIN,
          data: { messageDigest: branchMessageDigest(userCtx), origin: null },
        },
      ]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });
});

// verify-08.test.js — regression coverage for "fork 历史归属"
// (session-branch-history fork attribution: valid ancestor restore + independent body)
//
// Source under test: packages/cli/src/lib/session-branch-history.js
// Import path resolved relative to this deliverable (packages/cli/__tests__/verify-08.test.js).
import { describe, it, expect } from 'vitest';
import { createBranchHistoryImport } from '../../src/lib/session-branch-history.js';

// A stable 64-char hex value usable for sourceEventId / sourceGeneration / boundaryEvent.
const H64 = 'ab'.repeat(32);

// Event builders (shape follows the module's accept() contract).
const ev = (type, data) => ({ type, data });
const sessionStart = () => ev('session_start', { sessionId: 'sess-A' });
const branchStart = (history) => ev('session_branch', { history });
const message = (over) =>
  ev('session_branch_message', {
    role: 'user',
    text: '',
    part: 0,
    last: true,
    sourceEventId: H64,
    sourceItemIndex: 0,
    ...over,
  });
const contextMessage = (role) => ev('user_message', { role });

// A valid descriptor; individual fields are overridden for negative controls.
function descriptor(over = {}) {
  return {
    schema: 'v1',
    sourceGeneration: H64,
    totalMessages: 1,
    contextMessageCount: 1,
    coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
    ...over,
  };
}

// Feed a single logical branch through the importer and return every emitted result.
function runBranch(accept, { history, messages = [], contexts = [] }) {
  const out = [];
  const push = (r) => { out.push(r); return r; };
  accept(sessionStart());
  push(accept(branchStart(history)));
  for (const m of messages) push(accept(m));
  for (const c of contexts) push(accept(c));
  return out;
}

describe('fork history attribution (verify-08)', () => {
  it('restores two branches with valid ancestors and independent bodies (no bleed)', () => {
    const accept = createBranchHistoryImport().accept;

    // Branch A: one archived user message, one context message.
    const outA = runBranch(accept, {
      history: descriptor(),
      messages: [message({ text: 'branch-A body', part: 0, last: true })],
      contexts: [contextMessage('user')],
    });
    expect(outA[0]).toMatchObject({ kind: 'start' });
    expect(outA[1]).toMatchObject({ kind: 'archive', message: { role: 'user', content: 'branch-A body' } });
    expect(outA[2]).toMatchObject({ kind: 'context' });

    // Branch B: same structure but a distinct body must be archived on its own turn,
    // and branch-A content must not reappear in B's stream.
    const outB = runBranch(accept, {
      history: descriptor({ sourceGeneration: 'cd'.repeat(32) }),
      messages: [message({ text: 'branch-B body', part: 0, last: true })],
      contexts: [contextMessage('user')],
    });
    expect(outB[1]).toMatchObject({ kind: 'archive', message: { role: 'user', content: 'branch-B body' } });
    expect(outB[1].message.content).not.toContain('branch-A');
    // A's own body is exactly what it restored; B's body is distinct and independent.
    expect(outA[1].message.content).not.toContain('branch-B');
  });

  it('rejects an unsupported branch schema on a valid ancestor descriptor', () => {
    const accept = createBranchHistoryImport().accept;
    const bad = descriptor({ schema: 'bogus-schema' });
    expect(() => accept(branchStart(bad))).toThrow();
  });

  it('rejects a message whose part does not follow the expected part sequence', () => {
    const accept = createBranchHistoryImport().accept;
    accept(sessionStart());
    expect(() => accept(branchStart(descriptor()))).not.toThrow();
    // First message for a fresh branch must have part 0; starting at 1 is invalid.
    expect(() => accept(message({ part: 1, last: true, text: 'x' }))).toThrow();
  });

  it('rejects an invalid sourceEventId on an archived message', () => {
    const accept = createBranchHistoryImport().accept;
    accept(sessionStart());
    accept(branchStart(descriptor()));
    expect(() => accept(message({ sourceEventId: 'not-a-hash', text: 'x' }))).toThrow();
  });

  it('rejects a context message once the declared context count is exhausted (boundary)', () => {
    const accept = createBranchHistoryImport().accept;
    // contextMessageCount 0 is a valid boundary: no context message may follow the archive.
    accept(sessionStart());
    accept(branchStart(descriptor({ contextMessageCount: 0 })));
    accept(message({ text: 'body', part: 0, last: true }));
    // The next context message exceeds the declared count and must be rejected.
    expect(() => accept(contextMessage('user'))).toThrow();
  });

  it('rejects an archive message after the declared total message count', () => {
    const accept = createBranchHistoryImport().accept;
    accept(sessionStart());
    accept(branchStart(descriptor({ totalMessages: 1 })));
    accept(message({ text: 'first', part: 0, last: true }));
    // A second archive message overflows totalMessages and must be rejected.
    expect(() => accept(message({ text: 'second', part: 0, last: true }))).toThrow();
  });
});

// verify-08: fork history attribution for session-branch-history import.
// Frozen source: packages/cli/src/lib/session-branch-history.js (read-only).
// Acceptance: two branches each restore a valid ancestor and an independent
// body; content after a branch must not bleed into the other branch.
// Behavioral positive/negative controls over the public accept() stream.
import { describe, it, expect } from 'vitest';
import { createBranchHistoryImport } from '../../src/lib/session-branch-history';

const HASH = 'a'.repeat(64); // 64-hex source generation / source event id
const SCHEMA = 'chainlesschain.session-branch-history/v1';

// Build a valid event stream for a single branch import with `body` text and
// descriptor counts. Returns the accept() results so a caller can assert the
// exact body that was actually attributed to this branch.
function importBody(acceptor, opts) {
  const { totalMessages = 1, contextMessageCount = 0, body } = opts;
  const results = [];
  results.push(
    acceptor.accept({ type: 'session_branch', data: { history: {
      schema: SCHEMA,
      sourceGeneration: HASH,
      totalMessages,
      contextMessageCount,
      coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
    } } }),
  );
  for (let i = 0; i < totalMessages; i += 1) {
    results.push(
      acceptor.accept({ type: 'session_history_message', data: {
        role: 'user',
        text: body,
        part: i,
        last: true,
        sourceEventId: HASH,
        sourceItemIndex: i,
      } }),
    );
  }
  return results;
}

describe('fork history attribution (verify-08)', () => {
  it('restores a valid branch body with a recoverable ancestor', () => {
    const acceptor = createBranchHistoryImport();
    acceptor.accept({ type: 'session_start', data: { sessionId: 's0' } });
    const results = importBody(acceptor, { body: 'A-body' });
    const archives = results.filter((r) => r && r.kind === 'archive');
    expect(archives.length).toBe(1);
    expect(JSON.stringify(archives[0])).toContain('A-body');
  });

  it('keeps the two branch bodies independent: no bleed across branches', () => {
    const acceptor = createBranchHistoryImport();
    acceptor.accept({ type: 'session_start', data: { sessionId: 's0' } });
    const a = importBody(acceptor, { body: 'A-body' });
    const b = importBody(acceptor, { body: 'B-body' });
    const aArchives = a.filter((r) => r && r.kind === 'archive');
    const bArchives = b.filter((r) => r && r.kind === 'archive');
    // A's body is attributed to A only.
    expect(JSON.stringify(aArchives)).toContain('A-body');
    expect(JSON.stringify(aArchives)).not.toContain('B-body');
    // B's body is attributed to B only and is independent of A's content.
    expect(JSON.stringify(bArchives)).toContain('B-body');
    expect(JSON.stringify(bArchives)).not.toContain('A-body');
  });

  it('rejects a descriptor whose schema is outside the allowed set', () => {
    const acceptor = createBranchHistoryImport();
    acceptor.accept({ type: 'session_start', data: { sessionId: 's0' } });
    expect(() =>
      acceptor.accept({ type: 'session_branch', data: { history: {
        schema: 'not-a-schema',
        sourceGeneration: HASH,
        totalMessages: 1,
        contextMessageCount: 0,
        coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
      } } }),
    ).toThrow(/SESSION_BRANCH_HISTORY_INVALID/);
  });

  it('rejects an archive row whose role is outside user/assistant/tool', () => {
    const acceptor = createBranchHistoryImport();
    acceptor.accept({ type: 'session_start', data: { sessionId: 's0' } });
    const branch = acceptor.accept({ type: 'session_branch', data: { history: {
      schema: SCHEMA,
      sourceGeneration: HASH,
      totalMessages: 1,
      contextMessageCount: 0,
      coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
    } } });
    expect(branch && branch.kind).toBe('start');
    expect(() =>
      acceptor.accept({ type: 'session_history_message', data: {
        role: 'system',
        text: 'bad',
        part: 0,
        last: true,
        sourceEventId: HASH,
        sourceItemIndex: 0,
      } }),
    ).toThrow(/SESSION_BRANCH_HISTORY_INVALID/);
  });

  it('rejects a non-integer totalMessages in the descriptor', () => {
    const acceptor = createBranchHistoryImport();
    acceptor.accept({ type: 'session_start', data: { sessionId: 's0' } });
    expect(() =>
      acceptor.accept({ type: 'session_branch', data: { history: {
        schema: SCHEMA,
        sourceGeneration: HASH,
        totalMessages: 1.5,
        contextMessageCount: 0,
        coverage: { kind: 'from-origin', boundaryEvent: null, reason: null },
      } } }),
    ).toThrow(/SESSION_BRANCH_HISTORY_INVALID/);
  });

  it('rejects a complete event before the branch body is fully archived', () => {
    const acceptor = createBranchHistoryImport();
    acceptor.accept({ type: 'session_start', data: { sessionId: 's0' } });
    // Declares 2 messages but only archives 1; complete cannot close cleanly.
    importBody(acceptor, { totalMessages: 2, body: 'only-one' });
    expect(() =>
      acceptor.accept({ type: 'session_branch_complete', data: {
        schemaVersion: 2,
        messageCount: 0,
      } }),
    ).toThrow(/SESSION_BRANCH_HISTORY_INVALID/);
  });
});

