import { describe, it, expect } from "vitest";
import {
  createBranchHistoryImport,
  BRANCH_HISTORY_MESSAGE,
  BRANCH_HISTORY_ORIGIN,
  BRANCH_HISTORY_SCHEMA,
  branchMessageDigest,
} from "../src/lib/session-branch-history.js";

const HEX = (ch) => ch.repeat(64);

/**
 * Feed events into a fresh branch-history importer and collect every return
 * value, or let the importer's validation error propagate.
 */
function feed(events) {
  const importer = createBranchHistoryImport();
  const results = [];
  for (const event of events) {
    results.push(importer.accept(event));
  }
  return results;
}

function descriptor({ totalMessages, contextMessageCount }) {
  return {
    schema: BRANCH_HISTORY_SCHEMA,
    sourceGeneration: HEX("a"),
    totalMessages,
    contextMessageCount,
    coverage: { kind: "from-origin", boundaryEvent: null, reason: null },
  };
}

function start(sessionId) {
  return { type: "session_start", data: { sessionId } };
}

function branchEvent(desc) {
  return { type: "session_branch", data: { history: desc } };
}

function row(role, text, i) {
  return {
    type: BRANCH_HISTORY_MESSAGE,
    data: {
      role,
      text,
      part: 0,
      last: true,
      sourceEventId: HEX(String(i + 1)),
      sourceItemIndex: i,
    },
  };
}

const archive = (results) =>
  results
    .filter((r) => r && r.kind === "archive")
    .map((r) => r.message);

describe("fork history attribution (verify-08)", () => {
  it("recovers each branch's independent body without cross-leak", () => {
    const branchA = feed([
      start("a"),
      branchEvent(descriptor({ totalMessages: 2, contextMessageCount: 0 })),
      row("user", "A1", 0),
      row("assistant", "A2", 1),
    ]);
    expect(branchA[0]).toEqual({
      kind: "start",
      coverage: { kind: "from-origin", boundaryEvent: null, reason: null },
    });
    expect(archive(branchA)).toEqual([
      { role: "user", content: "A1" },
      { role: "assistant", content: "A2" },
    ]);

    const branchB = feed([
      start("b"),
      branchEvent(descriptor({ totalMessages: 1, contextMessageCount: 0 })),
      row("assistant", "B1", 0),
    ]);
    expect(archive(branchB)).toEqual([{ role: "assistant", content: "B1" }]);

    // Post-branch content must never leak into a sibling branch's body.
    expect(archive(branchB)[0].content).toBe("B1");
    expect(archive(branchB)[0].content).not.toContain("A1");
    expect(archive(branchA).map((m) => m.content).join()).not.toContain("B1");
  });

  it("rejects ancestry content when the branch declares no context slots", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 0 });
    expect(() =>
      feed([start("x"), branchEvent(desc), row("user", "pre", 0), {
        type: "user_message",
        data: { role: "user" },
      }]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("rejects a context event whose role does not match its event type", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 1 });
    expect(() =>
      feed([start("x"), branchEvent(desc), row("user", "pre", 0), {
        type: "user_message",
        data: { role: "assistant" },
      }]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("rejects body rows beyond the branch's declared totalMessages", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 0 });
    expect(() =>
      feed([
        start("x"),
        branchEvent(desc),
        row("user", "one", 0),
        row("assistant", "overflow", 1),
      ]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("rejects a completion with a non-v2 schema even when counts align", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 0 });
    expect(() =>
      feed([
        start("x"),
        branchEvent(desc),
        row("user", "one", 0),
        { type: "session_branch_complete", data: { schemaVersion: 1 } },
      ]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });

  it("resolves a context message's ancestry origin within the branch's own rows", () => {
    const desc = descriptor({ totalMessages: 1, contextMessageCount: 1 });
    const userCtx = { role: "user" };

    // Positive: a non-null origin pointing at an archived row is accepted.
    const positive = feed([
      start("x"),
      branchEvent(desc),
      row("user", "pre", 0),
      { type: "user_message", data: userCtx },
      {
        type: BRANCH_HISTORY_ORIGIN,
        data: {
          messageDigest: branchMessageDigest(userCtx),
          origin: { first: 0, last: 0 },
        },
      },
    ]);
    expect(positive.map((r) => r && r.kind)).toContain("context");

    // Negative: a null origin is only valid for a system role, so the same
    // user-context stream is rejected when origin is null.
    expect(() =>
      feed([
        start("x"),
        branchEvent(desc),
        row("user", "pre", 0),
        { type: "user_message", data: userCtx },
        {
          type: BRANCH_HISTORY_ORIGIN,
          data: { messageDigest: branchMessageDigest(userCtx), origin: null },
        },
      ]),
    ).toThrow(expect.objectContaining({ code: "SESSION_BRANCH_HISTORY_INVALID" }));
  });
});

